Choose indices to pool


Code
viewof chosen_indices = Inputs.checkbox(all_indices, {label: "Chosen indices", format: d =&gt; `${d.name} — ${d.seq}`, value: [all_indices[0], all_indices[1], all_indices[2], all_indices[3], all_indices[4], all_indices[5], all_indices[6], all_indices[7]]})









Code
positions = [0, 1, 2, 3, 4, 5]

color_check = positions.map(i =&gt; {
  const bases = chosen_indices.map(idx =&gt; idx.seq[i]);
  const hasAC = bases.some(b =&gt; b === "A" || b === "C");
  const hasTG = bases.some(b =&gt; b === "T" || b === "G");
  return { position: i + 1, bases: bases.join(""), hasAC, hasTG, ok: hasAC && hasTG };
})

all_ok = chosen_indices.length &gt;= 2 && color_check.every(r =&gt; r.ok)

























